/* W10_R01_SEARCH_V3_FREE */
const c=$json.candidate||null;if(!c)return [];
const t=String(c.title||'').toLowerCase();let intent=String(c.intent||'').trim();
if(!intent){if(t.includes('things to do'))intent='things_to_do';else if(t.includes('places to visit'))intent='places_to_visit';else if(t.includes('before visiting')||t.includes('know before'))intent='before_visiting';else if(t.includes('facts about'))intent='location_facts';else intent='general_facts';}
let query;
if(String(c.category)==='travel'){
 if(intent==='things_to_do')query=`${c.title} ${c.subject} official tourism attractions museums parks UNESCO`;
 else if(intent==='places_to_visit')query=`${c.title} ${c.subject} official tourism destinations regions UNESCO`;
 else if(intent==='before_visiting')query=`${c.title} ${c.subject} official travel advice tourism transport culture practical`;
 else query=`${c.title} ${c.subject} official tourism geography history culture government`;
}else query=`${c.subject} facts explanation official background science history geography`;
const bingUrl='https://www.bing.com/search?format=rss&q='+encodeURIComponent(query)+'&cc=gb&setlang=en-GB';
return [{json:{candidate:{...c,intent},intent,query,bingUrl}}];

/* W10_R01_PARSE_BING_V1 */
const base=$('Prepare evidence search').item.json;
const xml=String($json?.body||$json?.data||'');
const dec=s=>String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
const tag=(block,name)=>{const m=block.match(new RegExp('<'+name+'[^>]*>([\\s\\S]*?)<\\/'+name+'>','i'));return m?dec(m[1]):'';};
const blocks=[...xml.matchAll(/<item\b[^>]*>([\s\S]*?)<\/item>/gi)].map(m=>m[1]);
const out=[];const seen=new Set();
for(const b of blocks){const url=tag(b,'link');const title=tag(b,'title');const snippet=tag(b,'description');if(!/^https?:\/\//i.test(url)||!title||seen.has(url))continue;seen.add(url);out.push({url,title,snippet});if(out.length>=10)break;}
if(out.length<3)throw new Error(`Bing RSS returned only ${out.length} usable sources`);
return out.map((r,i)=>({json:{candidate:base.candidate,intent:base.intent,query:base.query,source_id:i+1,url:r.url,title:r.title,snippet:r.snippet,reader_url:'https://r.jina.ai/'+r.url}}));

/* W10_R01_ASSEMBLE_FREE_EVIDENCE_V1 */
const base=$('Prepare evidence search').item.json;
const meta=$('Parse Bing evidence').all().map(x=>x.json);
const fetched=$input.all().map(x=>x.json||{});
const clean=s=>String(s||'').replace(/\s+/g,' ').trim();
const rows=[];
for(let i=0;i<meta.length;i++){const m=meta[i],f=fetched[i]||{};let body=clean(f.body||f.data||'');if(body.length<120)body=clean(m.snippet);if(!m.url||body.length<60)continue;rows.push({source_id:rows.length+1,url:m.url,title:m.title,content:body.slice(0,5000),snippet:clean(m.snippet).slice(0,800)});}
if(rows.length<3)throw new Error(`Only ${rows.length} readable evidence sources after free fetch`);
return [{json:{candidate:base.candidate,intent:base.intent,query:base.query,evidence:rows,evidence_provider:'bing_rss+jina_reader'}}];

/* W10_R01_PROMPT_V3 */
const c=$json.candidate;const intent=$json.intent;const rows=Array.isArray($json.evidence)?$json.evidence:[];
if(rows.length<3)throw new Error('Fewer than three usable evidence sources returned');
let intentRules='Each fact must be a distinct, durable claim directly supported by at least one chosen source.';
if(String(c.category)==='travel'&&intent==='things_to_do')intentRules='Produce exactly 10 distinct places, attractions or experiences a visitor could realistically consider. Each item title should name the place or experience. Explain why it is worth considering and where/what it is. Prefer durable attractions over temporary events. Do not state current prices or opening hours unless the supplied evidence clearly dates them.';
else if(String(c.category)==='travel'&&intent==='places_to_visit')intentRules='Produce exactly 10 distinct destinations, neighbourhoods, islands, regions or attractions that are genuinely useful choices for a visitor. Make the geographic relationship clear and avoid padding the list with near-duplicates.';
else if(String(c.category)==='travel'&&intent==='before_visiting')intentRules='Produce exactly 10 durable planning points a visitor should understand before travelling. Prioritise transport, geography, customs, practical norms and official travel information. Avoid volatile visa, safety, price or entry claims unless directly supported and clearly framed as time-sensitive.';
else if(String(c.category)==='travel'&&intent==='location_facts')intentRules='Produce exactly 10 interesting, durable facts about the location, spanning geography, history, culture, landmarks or environment where the supplied evidence supports them.';
const system=`You research evidence-backed What10Things explainers. Return STRICT JSON only. Use ONLY supplied evidence. Never use unstated memory, never invent a source, and never convert a current event into live-news reporting. Output: {title,summary,intro,reading_time,items:[EXACTLY 10],related_topics:[0..6]}. Each item: {title,body,confidence,source_ids:[1..10]}. related_topics: {slug,title,subject,category,relationship,score,evergreen_score,rationale}. ${intentRules} body 60-220 words, plain UK English. confidence 0.70..0.95; lower it when evidence is indirect. For travel, strongly prefer official tourism boards, government, UNESCO, national parks, museums and other authoritative destination sources where present, then reputable independent sources. Do not claim hands-on testing or original reporting. Related topics must be evergreen and genuinely useful. For travel topics, favour related cities, regions, landmarks and companion destination guides so the site can grow into a connected travel guide.`;
const user=JSON.stringify({candidate:{title:c.title,subject:c.subject,category:c.category,rationale:c.rationale,intent:c.intent||intent,destination:c.destination||null},evidence:rows});
return [{json:{candidate:c,evidence:rows,intent,evidence_provider:$json.evidence_provider,system,user}}];

/* W10_R01_VALIDATE_V3 */
const base=$('Build evidence-grounded research prompt').item.json;const c=base.candidate;const evidence=base.evidence||[];const byId=new Map(evidence.map(x=>[Number(x.source_id),x]));
const raw=String($json?.choices?.[0]?.message?.content||'').replace(/```json|```/gi,'').trim();let x=null;try{x=JSON.parse(raw);}catch{}
const slugify=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120);const host=u=>{try{return new URL(u).hostname.replace(/^www\./,'')}catch{return ''}};
const allowed=new Set(['science-nature','world','history-culture','general-knowledge','technology','travel','home-living','money','everyday','buying-guides']);
let error='';let topic=null;
if(!x||!Array.isArray(x.items)){error='Free model did not return valid topic JSON';}
else{const items=[];for(const f of x.items){if(items.length>=10)break;const title=String(f?.title||'').trim(),body=String(f?.body||'').replace(/\s+/g,' ').trim();const ids=[...new Set((Array.isArray(f?.source_ids)?f.source_ids:[]).map(Number).filter(n=>byId.has(n)))];if(title.length<5||body.length<40||!ids.length)continue;const conf=Math.max(.70,Math.min(.95,Number(f.confidence)||.72));const sources=ids.slice(0,3).map(id=>{const s=byId.get(id);const domain=host(s.url);return {url:s.url,title:s.title,publisher:domain,source_type:/\.gov\.uk$|\.gov$|nhs\.uk$|\.edu$|\.ac\.uk$|unesco\.org$/i.test(domain)?'official':'independent',evidence_excerpt:String(s.content||'').slice(0,650)};});items.push({title,body,confidence:conf,sources});}
 if(items.length!==10){error=`Research produced ${items.length} valid sourced facts instead of 10`;}
 else{const rel=[];for(const r of (Array.isArray(x.related_topics)?x.related_topics:[]).slice(0,6)){const slug=slugify(r?.slug||r?.subject||r?.title);const cat=allowed.has(String(r?.category))?String(r.category):String(c.category||'general-knowledge');const score=Math.max(0,Math.min(1,Number(r?.score)||.65)),ever=Math.max(0,Math.min(1,Number(r?.evergreen_score)||score));if(slug&&slug!==c.slug&&score>=.65&&ever>=.70)rel.push({slug,title:String(r?.title||slug.replace(/-/g,' ')).slice(0,300),subject:String(r?.subject||r?.title||slug.replace(/-/g,' ')).slice(0,300),category:cat,relationship:String(r?.relationship||'related').slice(0,80),score,evergreen_score:ever,rationale:String(r?.rationale||'Related evidence-backed follow-up subject.').slice(0,1200)});} const domains=new Set(items.flatMap(i=>i.sources.map(s=>host(s.url))).filter(Boolean));const quality=Math.min(.92,.76+Math.min(.12,domains.size*.02));topic={slug:c.slug,title:String(x.title||c.title).slice(0,300),category:allowed.has(String(c.category))?String(c.category):'general-knowledge',summary:String(x.summary||`Ten sourced points about ${c.subject}.`).slice(0,600),intro:String(x.intro||`An evidence-backed introduction to ${c.subject}, built from retrievable sources.`).slice(0,1800),reading_time:String(x.reading_time||'7 min read').slice(0,40),quality_score:quality,trigger:{source:String(c.source_kind||'research_pipeline'),query:c.subject,signal_id:c.signal_id||null},generation:{workflow:'W10-R01 Evidence Research',execution:String($execution.id),source_count:evidence.length,intent:String(c.intent||base.intent||'general_facts'),evidence_provider:String(base.evidence_provider||'free_web')},items,related_topics:rel};}}
return [{json:{candidate_id:c.id,status:topic?'published':'retry',topic,error}}];
